package net.officefloor.hq.app.claim;

import java.util.List;
import java.util.Optional;
import jakarta.persistence.LockModeType;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Lock;
import org.springframework.data.jpa.repository.Modifying;
import org.springframework.data.jpa.repository.Query;

public interface ClaimRepository extends JpaRepository<Claim, Long> {

    /** The highest claim id on any sheet; 0 with none. */
    @Query("select coalesce(max(c.id), 0) from Claim c")
    long maxId();

    /** A sheet's claims, newest first. */
    List<Claim> findBySheetIdOrderByIdDesc(String sheetId);

    /** A sheet's claims as listed: the latest list place (the newest added, or the last reassigned) first. */
    List<Claim> findBySheetIdOrderByListedDescIdDesc(String sheetId);

    List<Claim> findBySheetIdAndPersonIdOrderByIdAsc(String sheetId, Long personId);

    Optional<Claim> findByIdAndSheetId(Long id, String sheetId);

    /** The person's claim with the number (numbers are unique on a sheet). */
    Optional<Claim> findBySheetIdAndPersonIdAndNumber(String sheetId, Long personId, String number);

    /** Whether a claim on the sheet has the reference, compared without regard to case. */
    boolean existsBySheetIdAndRefIgnoreCase(String sheetId, String ref);

    /** Whether a claim on the sheet other than the one with the id has the reference, compared without regard to case. */
    boolean existsBySheetIdAndRefIgnoreCaseAndIdNot(String sheetId, String ref, Long id);

    /** The claim, locked until the transaction ends, so two changes of its status do not interleave. */
    @Lock(LockModeType.PESSIMISTIC_WRITE)
    @Query("select c from Claim c where c.id = :id and c.sheetId = :sheetId")
    Optional<Claim> findForUpdate(Long id, String sheetId);

    /** Release every claim editor's lock on the sheet. */
    @Modifying(flushAutomatically = true)
    @Query("update Claim c set c.lockedBy = null where c.sheetId = :sheetId and c.lockedBy is not null")
    int unlockAll(String sheetId);
}
package net.officefloor.hq.app.person;

import java.util.Collection;
import java.util.List;
import java.util.Optional;
import jakarta.persistence.LockModeType;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Lock;
import org.springframework.data.jpa.repository.Query;

public interface PersonRepository extends JpaRepository<Person, Long> {

    /** A sheet's people in list order: by position, then in the order they were added. */
    List<Person> findBySheetIdOrderByPositionAscIdAsc(String sheetId);

    /** The highest position on the sheet; 0 when it has no people. */
    @Query("select coalesce(max(p.position), 0) from Person p where p.sheetId = :sheetId")
    long maxPosition(String sheetId);

    Optional<Person> findByIdAndSheetId(Long id, String sheetId);

    /** The person, locked until the transaction ends, so two statements of them do not interleave. */
    @Lock(LockModeType.PESSIMISTIC_WRITE)
    @Query("select p from Person p where p.id = :id and p.sheetId = :sheetId")
    Optional<Person> findForUpdate(Long id, String sheetId);

    /** Whether a person on the sheet, other than the one with this id, has the name key. */
    boolean existsBySheetIdAndNameKeyAndIdNot(String sheetId, String nameKey, Long id);

    boolean existsBySheetIdAndNameKey(String sheetId, String nameKey);

    /** Whether a person on the sheet, other than the one with this id, has the contact. */
    boolean existsBySheetIdAndContactAndIdNot(String sheetId, String contact, Long id);

    boolean existsBySheetIdAndContact(String sheetId, String contact);

    Optional<Person> findBySheetIdAndNameKey(String sheetId, String nameKey);

    /** Whether a person on any of the sheets, other than the one with this id, has the name key. */
    boolean existsBySheetIdInAndNameKeyAndIdNot(Collection<String> sheetIds, String nameKey, Long id);

    /** The name keys of the people on the sheets. */
    @Query("select p.nameKey from Person p where p.sheetId in :sheetIds")
    List<String> findNameKeysBySheetIdIn(Collection<String> sheetIds);
}
package net.officefloor.hq.app.claim;

/**
 * Where a claim is in its life: DRAFT, then OPEN, then SETTLED. A clerk settling an OPEN claim whose due is above the
 * clerk limit sends it to PENDING instead, which a steward approves (SETTLED) or rejects (back to OPEN). A DRAFT, OPEN
 * or PENDING claim may be VOID; a steward may also void a SETTLED one shortly after its settlement (see ClaimService).
